'use strict';
const assert=require('node:assert/strict');
const p=require('./album-palette.js');
const pixels=(...rows)=>Uint8ClampedArray.from(rows.flat());
const rgb=hex=>[1,3,5].map(i=>parseInt(hex.slice(i,i+2),16));
const lum=hex=>rgb(hex).map(x=>{x/=255;return x<=.04045?x/12.92:((x+.055)/1.055)**2.4}).reduce((a,x,i)=>a+x*[.2126,.7152,.0722][i],0);
assert.deepEqual(p.paletteFromPixels(pixels([255,0,0,0])),p.neutral());
const red=p.paletteFromPixels(pixels([220,40,30,255]));
assert.ok(rgb(red.base)[0]>rgb(red.base)[1]);
const blue=p.paletteFromPixels(pixels([30,50,220,255]));
assert.ok(rgb(blue.base)[2]>rgb(blue.base)[0]);
const gray=p.paletteFromPixels(pixels([255,255,255,255]));
assert.equal(new Set(rgb(gray.base)).size,1);
for(const c of [red,blue,gray,p.paletteFromPixels(pixels([255,255,0,255])),p.paletteFromPixels(pixels([0,255,0,255]))])assert.ok(1.05/(lum(c.base)+.05)>=4.5);
assert.equal(p.approvedUrl('https://i.scdn.co/image/a'),'https://i.scdn.co/image/a');
assert.equal(p.approvedUrl('https://i.scdn.co.evil.test/image/a'),'');
assert.equal(p.approvedUrl('http://i.scdn.co/image/a'),'');
assert.equal(p.approvedUrl('https://user@i.scdn.co/image/a'),'');
assert.equal(p.fromImage({}, {createElement(){throw Error('tainted')}}),null);
let drawn=0;
const doc={createElement(tag){return tag==='canvas'?{getContext(){return {drawImage(){drawn++},getImageData(){return {data:pixels([220,40,30,255])}}}}}:{tag}}};
const album={children:[],replaceChildren(...nodes){this.children=nodes},append(n){this.children.push(n)}};
let updates=[];
const c=p.createController(doc,(col,url)=>updates.push({col,url}));
const a='https://i.scdn.co/image/a',b='https://i.scdn.co/image/b';
c.mount(album,a,()=>true);
const old=album.children[0];
assert.equal(old.crossOrigin,'anonymous');
c.mount(album,b,()=>true);
const next=album.children[0],before=updates.length;
old.onload();assert.equal(updates.length,before);
next.onload();assert.equal(updates.at(-1).url,b);assert.equal(drawn,1);
c.mount(album,b,()=>true);album.children[0].onload();assert.equal(drawn,1);
c.mount(album,a,()=>true);album.children[0].onerror();
assert.equal(album.children[0].crossOrigin,undefined);
album.children[0].onload();assert.deepEqual(updates.at(-1).col,p.neutral());
c.mount(album,'',()=>true);assert.equal(updates.at(-1).url,'');
c.mount(album,a,()=>false);const n=updates.length;album.children[0].onload();assert.equal(updates.length,n);
console.log('Album palette tests passed');
